const order = $input.first().json;
const customer = order.customer ?? {};
const email = (customer.email ?? '').toLowerCase().trim();
const firstName = customer.first_name ?? email.split('@')[0] ?? '';
const lastName = customer.last_name ?? '';
const totalZar = (order.total ?? 0) / 100;
const createdAt = order.created_at ?? new Date().toISOString();

const productNames = (order.items ?? []).map(item => {
  const product = item.variant?.product?.title ?? item.title ?? 'Unknown';
  const variant = item.variant?.title;
  return variant && variant !== 'Default' ? `${product} — ${variant}` : product;
}).join(', ');

const vtigerUrl = $env.VTIGER_URL?.replace(/\/$/, '') ?? '';
const vtigerUser = $env.VTIGER_USERNAME ?? '';
const vtigerKey = $env.VTIGER_ACCESS_KEY ?? '';

if (!vtigerUrl || !vtigerUser || !vtigerKey) {
  throw new Error('Vtiger env vars not set in n8n');
}

return [{
  json: {
    email,
    firstName,
    lastName,
    totalZar,
    createdAt,
    productNames,
    orderId: order.id,
    displayId: order.display_id,
    vtigerUrl,
    vtigerUser,
    vtigerKey,
  }
}];

const prep = $('Prepare: Extract Order Data').first().json;
const challenge = $input.first().json;
if (!challenge.success) throw new Error('Vtiger getchallenge failed: ' + JSON.stringify(challenge));
const { createHash } = require('crypto');
const accessKeyHash = createHash('md5').update(challenge.result.token + prep.vtigerKey).digest('hex');
return [{ json: { ...prep, accessKeyHash } }];

const prep = $('Prepare: Build Login Hash').first().json;
const loginResult = $input.first().json;
if (!loginResult.success) throw new Error('Vtiger login failed: ' + JSON.stringify(loginResult));
const sessionName = loginResult.result.sessionName;
const safeEmail = prep.email.replace(/'/g, "\\'");
return [{ json: { ...prep, sessionName, safeEmail } }];

// Update existing contact — increment total_spend_zar, set last_purchase_date.
const prep = $('Prepare: Session').first().json;
const findResult = $('Vtiger: Find Contact').first().json;
const existing = findResult.result[0];
const existingSpend = parseFloat(existing.cf_total_spend_zar ?? '0') || 0;
const newSpend = (existingSpend + prep.totalZar).toFixed(2);

const element = JSON.stringify({
  id: existing.id,
  cf_last_purchase_date: prep.createdAt.slice(0, 10),
  cf_total_spend_zar: String(newSpend),
  cf_pipeline_stage: 'Closed Won',
});

return [{ json: { ...prep, contactId: existing.id, element, isNew: false } }];

// Create new contact with Shop as lead source.
const prep = $('Prepare: Session').first().json;
const element = JSON.stringify({
  email: prep.email,
  firstname: prep.firstName || prep.email.split('@')[0],
  lastname: prep.lastName || '',
  leadsource: 'Shop',
  cf_last_purchase_date: prep.createdAt.slice(0, 10),
  cf_total_spend_zar: String(prep.totalZar.toFixed(2)),
  cf_pipeline_stage: 'Closed Won',
});
return [{ json: { ...prep, element, isNew: true } }];

// Resolve final contactId after upsert.
const prep = $input.first().json;
const upsertResult = $input.first().json;

// If update branch, contactId was already in prep
let contactId = prep.contactId ?? null;
if (!contactId && upsertResult.success) {
  contactId = upsertResult.result?.id ?? null;
}
if (!contactId) throw new Error('Could not resolve contactId for ' + prep.email);

return [{ json: { ...prep, contactId } }];

const prep = $input.first().json;
const totalDisplay = `R${prep.totalZar.toFixed(2)}`;
const subject = `Purchase — ${prep.productNames}, ${totalDisplay}`;
const element = JSON.stringify({
  activitytype: 'Call',
  subject: subject.slice(0, 255),
  description: `Order ID: ${prep.orderId}. Products: ${prep.productNames}. Total: ${totalDisplay}`,
  contact_id: prep.contactId,
  date_start: prep.createdAt.slice(0, 10),
  time_start: new Date(prep.createdAt).toTimeString().slice(0, 8),
  eventstatus: 'Held',
});
return [{ json: { ...prep, element } }];

const prep = $('Merge: Resolve Contact ID').first().json;
console.log('[order-vtiger] SUCCESS orderId=' + prep.orderId + ' contactId=' + prep.contactId);
return [$input.first()];

const errItem = $input.first();
const errorMessage = errItem.error?.message ?? errItem.json?.message ?? 'Unknown error';
let email = 'unknown';
try { email = $('Prepare: Extract Order Data').first().json.email ?? 'unknown'; } catch {}
console.error('[order-vtiger] ERROR email=' + email + ' error=' + errorMessage);
return [{ json: { email, errorMessage, subject: '[ALERT] Medusa → Vtiger sync failed for ' + email, timestamp: new Date().toISOString() } }];
